// Package units keeps the systemd units generated by ffnvr in sync with the configuration:
// every file /etc/systemd/system/ffnvr-*.service belongs to ffnvr, is (re)written from the
// configuration, and is stopped and deleted when the configuration no longer has it.
package units

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const (
	Dir    = "/etc/systemd/system"
	Prefix = "ffnvr-"
	Suffix = ".service"
)

// Unit is the desired content of one unit file.
type Unit struct {
	// Name: the unit's file name, e.g. ffnvr-nvr01-cam1.service; or the absolute path of
	// a configuration file a unit reads (one of ManagedFiles, written 0600: it may hold
	// passwords; no systemctl call of its own - its unit carries a hash of it)
	Name    string
	Content string
}

// ManagedFiles are the configuration files besides the units that ffnvr owns.
var ManagedFiles = []string{"/etc/ffnvr/go2rtc.yaml"}

// IsFile reports whether a name is a managed file rather than a unit.
func IsFile(name string) bool { return strings.HasPrefix(name, "/") }

func managed(name string) bool {
	for _, f := range ManagedFiles {
		if f == name {
			return true
		}
	}
	return false
}

func (p *Plan) path(name string) string {
	if IsFile(name) {
		return filepath.Join(p.Root, name)
	}
	return filepath.Join(p.Root, Dir, name)
}

func shown(name string) string {
	if IsFile(name) {
		return name
	}
	return filepath.Join(Dir, name)
}

// Kind of change of one unit.
type Kind int

const (
	Same Kind = iota
	Add
	Update
	Remove
)

// Change of one unit.
type Change struct {
	Name     string
	Kind     Kind
	Old, New string
}

// Plan is the set of changes making the units on disk match the configuration.
type Plan struct {
	Root    string
	Changes []Change // sorted by name
}

// Runner runs a command (systemctl ...). nil: commands are only printed.
type Runner func(args ...string) error

// Owned reports whether a unit file name belongs to ffnvr.
func Owned(name string) bool {
	return strings.HasPrefix(name, Prefix) && strings.HasSuffix(name, Suffix)
}

// NewPlan compares the wanted units with the files below root.
func NewPlan(root string, want []Unit) (*Plan, error) {
	p := &Plan{Root: root}
	byName := map[string]string{}
	for _, u := range want {
		if IsFile(u.Name) {
			if !managed(u.Name) {
				return nil, fmt.Errorf("%s is not a file ffnvr manages", u.Name)
			}
		} else if !Owned(u.Name) || strings.ContainsAny(u.Name, "/") {
			return nil, fmt.Errorf("invalid unit name %q", u.Name)
		}
		if _, dup := byName[u.Name]; dup {
			return nil, fmt.Errorf("unit %s generated twice", u.Name)
		}
		byName[u.Name] = u.Content
	}
	have := map[string]string{}
	ents, err := os.ReadDir(filepath.Join(root, Dir))
	if err != nil && !os.IsNotExist(err) {
		return nil, err
	}
	for _, e := range ents {
		if !e.Type().IsRegular() || !Owned(e.Name()) {
			continue
		}
		b, err := os.ReadFile(filepath.Join(root, Dir, e.Name()))
		if err != nil {
			return nil, err
		}
		have[e.Name()] = string(b)
	}
	for _, f := range ManagedFiles {
		if b, err := os.ReadFile(filepath.Join(root, f)); err == nil {
			have[f] = string(b)
		}
	}
	for name, content := range byName {
		old, ok := have[name]
		switch {
		case !ok:
			p.Changes = append(p.Changes, Change{name, Add, "", content})
		case old != content:
			p.Changes = append(p.Changes, Change{name, Update, old, content})
		default:
			p.Changes = append(p.Changes, Change{name, Same, old, content})
		}
	}
	for name, old := range have {
		if _, ok := byName[name]; !ok {
			p.Changes = append(p.Changes, Change{name, Remove, old, ""})
		}
	}
	sort.Slice(p.Changes, func(i, j int) bool { return p.Changes[i].Name < p.Changes[j].Name })
	return p, nil
}

// names of the units (not the files) with the given kinds of change.
func (p *Plan) names(kinds ...Kind) []string {
	var out []string
	for _, c := range p.Changes {
		if IsFile(c.Name) {
			continue
		}
		for _, k := range kinds {
			if c.Kind == k {
				out = append(out, c.Name)
			}
		}
	}
	return out
}

// Changed reports whether any unit file would be written or deleted.
func (p *Plan) Changed() bool { return len(p.names(Add, Update, Remove)) > 0 }

// FilesChanged reports whether anything, a unit or a file, would change.
func (p *Plan) FilesChanged() bool {
	for _, c := range p.Changes {
		if c.Kind != Same {
			return true
		}
	}
	return false
}

// commands returns the systemctl calls of the plan, in order: units to drop are stopped
// first, the files are reloaded, every wanted unit is enabled and started (a no-op for a
// running one) and the changed ones are restarted.
func (p *Plan) commands() [][]string {
	var cmds [][]string
	if rm := p.names(Remove); len(rm) > 0 {
		cmds = append(cmds, append([]string{"systemctl", "disable", "--now"}, rm...))
	}
	if p.Changed() {
		cmds = append(cmds, []string{"systemctl", "daemon-reload"})
	}
	if on := p.names(Add, Update, Same); len(on) > 0 {
		cmds = append(cmds, append([]string{"systemctl", "enable", "--now"}, on...))
	}
	if up := p.names(Update); len(up) > 0 {
		cmds = append(cmds, append([]string{"systemctl", "restart"}, up...))
	}
	return cmds
}

// WriteDiff prints what Apply would do.
func (p *Plan) WriteDiff(w io.Writer) {
	for _, c := range p.Changes {
		path := shown(c.Name)
		switch c.Kind {
		case Same:
			fmt.Fprintf(w, "# %s: unchanged\n", path)
		case Add:
			fmt.Fprint(w, UnifiedDiff("/dev/null", path, "", c.New))
		case Update:
			fmt.Fprint(w, UnifiedDiff(path, path, c.Old, c.New))
		case Remove:
			fmt.Fprint(w, UnifiedDiff(path, "/dev/null", c.Old, ""))
		}
	}
	for _, c := range p.commands() {
		fmt.Fprintf(w, "# would run: %s\n", strings.Join(c, " "))
	}
	if len(p.Changes) == 0 {
		fmt.Fprintln(w, "# no units")
	}
}

// Apply writes and deletes the unit files and runs systemctl through run (nil: skip it).
func (p *Plan) Apply(w io.Writer, run Runner) error {
	cmds := p.commands()
	exec := func(c []string) error {
		if run == nil {
			fmt.Fprintf(w, "skipped    %s\n", strings.Join(c, " "))
			return nil
		}
		fmt.Fprintf(w, "running    %s\n", strings.Join(c, " "))
		if err := run(c...); err != nil {
			return fmt.Errorf("%s: %w", strings.Join(c, " "), err)
		}
		return nil
	}
	// stop the units to drop while their files still exist
	if len(cmds) > 0 && cmds[0][1] == "disable" {
		if err := exec(cmds[0]); err != nil {
			fmt.Fprintf(w, "warning: %v\n", err) // the files go anyway
		}
		cmds = cmds[1:]
	}
	for _, c := range p.Changes {
		full := p.path(c.Name)
		switch c.Kind {
		case Remove:
			if err := os.Remove(full); err != nil && !os.IsNotExist(err) {
				return err
			}
			fmt.Fprintf(w, "removed    %s\n", shown(c.Name))
		case Add, Update:
			mode := os.FileMode(0o644)
			if IsFile(c.Name) {
				mode = 0o600 // may hold passwords
			}
			if err := writeFile(full, c.New, mode); err != nil {
				return err
			}
			fmt.Fprintf(w, "written    %s\n", shown(c.Name))
		}
	}
	for _, c := range cmds {
		if err := exec(c); err != nil {
			return err
		}
	}
	return nil
}

// writeFile replaces a file atomically.
func writeFile(full, content string, mode os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(full), ".ffnvr-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.WriteString(content); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Chmod(mode); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), full)
}
